import {validEditorTool,validToolInput,runEditorTool,inspectEditorTool,editorToolOutput,editorToolCancelled} from './editor-tool-assets.js';
export class EditorTool {
 constructor(element,doc,hooks){this.el=element;this.doc=doc;this.hooks=hooks;this.values={};this.epoch=0;this.pending=null;this.disposed=false;this.last=null;this.render();}
 inspect(){return {...inspectEditorTool(this.doc.data,this.hooks.methods()),pending:!!this.pending,last:this.last?{...this.last}:null};}
 busy(){const busy=!!this.pending;this.form?.setAttribute('aria-busy',String(busy));for(const control of this.controls||[])control.disabled=busy||!!control.hbUnavailable;}
 status(){if(this.output)this.output.textContent=this.last?.output??(this.pending?'실행 중':this.last?.status==='failed'?this.last.message:'');}
 render(){
  if(this.disposed)return;this.epoch++;const compatibility=inspectEditorTool(this.doc.data,this.hooks.methods());this.values=Object.fromEntries(this.doc.data.inputs.filter(f=>Object.hasOwn(this.values,f.id)&&validToolInput(f,this.values[f.id])).map(f=>[f.id,this.values[f.id]]));this.controls=[];
  const owner=this.el.ownerDocument;this.el.replaceChildren();this.el.classList.add('editor-tool');const toolbar=owner.createElement('div');toolbar.className='document-toolbar';const title=owner.createElement('strong');title.textContent=this.doc.data.name;toolbar.append(title);this.el.append(toolbar);
  const form=this.form=owner.createElement('form');form.className='editor-tool-form';form.onsubmit=e=>e.preventDefault();this.el.append(form);
  for(const f of this.doc.data.inputs){const label=owner.createElement('label'),caption=owner.createElement('span');caption.textContent=f.label;label.append(caption);let control;const value=this.values[f.id]??f.default;
   if(f.type==='vec3'){control=owner.createElement('span');control.className='asset-vector-fields';for(let i=0;i<3;i++){const input=owner.createElement('input');this.controls.push(input);input.type='number';input.step='any';input.value=value[i];input.ariaLabel=f.label+' '+'XYZ'[i];input.onchange=()=>{const v=[...(this.values[f.id]??f.default)];v[i]=Number(input.value);this.values[f.id]=v;};const cell=owner.createElement('span'),axis=owner.createElement('span');cell.className='editor-tool-axis';cell.dataset.axis=i;axis.textContent='XYZ'[i];cell.append(axis,input);control.append(cell);}}
   else {control=owner.createElement(f.type==='select'?'select':'input');this.controls.push(control);if(f.type==='select')for(const c of f.choices){const option=owner.createElement('option');option.value=c.value;option.textContent=c.label;control.append(option);}else {control.type=f.type==='bool'?'checkbox':f.type==='number'?'number':'text';if(f.min!==undefined)control.min=f.min;if(f.max!==undefined)control.max=f.max;control.step='any';}if(f.type==='bool')control.checked=value;else control.value=value;control.onchange=()=>this.values[f.id]=f.type==='bool'?control.checked:f.type==='number'?Number(control.value):control.value;control.ariaLabel=f.label;}
   label.append(control);form.append(label);
  }
  const buttons=owner.createElement('div');buttons.className='editor-tool-actions';for(const a of this.doc.data.actions){const button=owner.createElement('button');this.controls.push(button);button.type='button';button.textContent=a.label;button.dataset.toolAction=a.id;button.hbUnavailable=this.doc.data.api?!compatibility.compatible:compatibility.missing.includes(a.method);button.onclick=async()=>{try{await this.run(a.id,this.values);}catch(error){if(!this.disposed&&error?.code!=='EDITOR_TOOL_CANCELLED')this.hooks.error(error?.message??String(error));}};buttons.append(button);}form.append(buttons);
  this.output=owner.createElement('output');this.output.dataset.toolOutput='';this.output.setAttribute('aria-live','polite');form.append(this.output);
  const details=owner.createElement('details'),summary=owner.createElement('summary'),source=owner.createElement('textarea'),apply=owner.createElement('button');this.controls.push(source,apply);summary.textContent='도구 편집';source.value=JSON.stringify(this.doc.data,null,2);source.ariaLabel='도구 정의';source.spellcheck=false;apply.textContent='적용';apply.type='button';apply.onclick=()=>{try{if(this.disposed)throw editorToolCancelled();if(this.pending)throw Error('앞선 도구 실행을 마친 뒤 수정하세요.');const data=JSON.parse(source.value);if(!validEditorTool(data))throw Error('도구 정의·API 버전을 확인하세요.');this.hooks.before();this.doc.data=data;this.hooks.change();this.last=null;this.render();}catch(error){if(error?.code!=='EDITOR_TOOL_CANCELLED')this.hooks.error(error?.message??String(error));}};details.append(summary,source,apply);this.el.append(details);this.busy();this.status();
 }
 async run(action,inputs={}){
  if(this.disposed)throw editorToolCancelled();if(this.pending)throw Error('앞선 도구 실행을 마친 뒤 다시 실행하세요.');const ticket={epoch:this.epoch,definition:this.doc.data,controller:new AbortController()},current=()=>!this.disposed&&this.pending===ticket&&this.epoch===ticket.epoch&&this.doc.data===ticket.definition;this.pending=ticket;this.last=null;this.busy();this.status();
  try{const result=await runEditorTool(ticket.definition,action,inputs,this.hooks.context(),this.hooks.methods(),{current,signal:ticket.controller.signal});if(current()){const definition=ticket.definition.actions.find(a=>a.id===action);let output='';if(definition.output==='json')try{output=editorToolOutput(result);}catch{output='결과를 표시할 수 없어요.';}this.last={action,status:'done',output};}return result;}
  catch(error){if(current()&&error?.code!=='EDITOR_TOOL_CANCELLED')this.last={action,status:'failed',message:error?.message??String(error)};throw error;}
  finally{if(this.pending===ticket)this.pending=null;if(!this.disposed){this.busy();this.status();}}
 }
 dispose(){this.disposed=true;this.epoch++;this.pending?.controller.abort();this.el.replaceChildren();this.controls=[];this.form=this.output=null;}
}
